-- (nhan xet mentor 04/11/2026 - 5 thay doi cot loi; xem docs/phan-luong-hoc-ky.md)
-- ----------------------------------------------------------------------------
-- THU TU TRIEN KHAI (ngoai gio hoc):
--   1) Chay TOAN BO file nay trong SQL Editor (1 transaction).
--   2) Deploy code moi (doc cac cot moi - chay code moi truoc migration se loi).
--   3) npm run recompute:profiles  (SCORING_VERSION v5: 3 nhom doi nghia, cau thay the, nhan luong).
-- An toan chay lai: cot "add column if not exists", noi dung "on conflict do nothing", va moi lenh SUA noi dung cu
-- (quiz, cac buoc, tai nguyen, trong so) chi chay khi gia tri trong DB VAN LA ban soan san cu => KHONG de len ban
-- giao vien da sua. Khong xoa dong nao: cau/hoat dong doi nghia chi bi cho nghi (active = false).
-- Sau khi chay: hoc sinh lop 9 HK1 duoc moi tra loi them 8 cau (3 cau neo thay the + 5 cau cua hoc ky), dap an cu
-- chon san. Giao vien doi hoc ky cho lop o trang Lop hoc.
-- Doi chieu: supabase/schema.sql, docs/data-dictionary.md. Phan noi dung (muc 2-4) SINH TU src/lib/content.
-- ============================================================================
begin;

-- 1) COT MOI ------------------------------------------------------------------
alter table class_groups add column if not exists curriculum_term text not null default 'G9_HK1'
  check (curriculum_term in ('G8_HK1', 'G8_HK2', 'G9_HK1', 'G9_HK2'));

alter table survey_questions add column if not exists curriculum_term text not null default 'ALL'
  check (curriculum_term in ('ALL', 'G8_HK1', 'G8_HK2', 'G9_HK1', 'G9_HK2'));
alter table survey_questions add column if not exists active boolean not null default true;
alter table survey_options add column if not exists track_weights jsonb not null default '{}';
alter table survey_attempts add column if not exists curriculum_term text
  check (curriculum_term in ('G8_HK1', 'G8_HK2', 'G9_HK1', 'G9_HK2'));

alter table activities add column if not exists curriculum_term text not null default 'ALL'
  check (curriculum_term in ('ALL', 'G8_HK1', 'G8_HK2', 'G9_HK1', 'G9_HK2'));

alter table potential_profiles add column if not exists recommended_track text
  check (recommended_track in ('VOCATIONAL_9PLUS', 'ACADEMIC_HIGH_SCHOOL', 'DUAL_EXPLORATION'));
alter table potential_profiles add column if not exists vocational_affinity_score numeric(5,2);
alter table potential_profiles add column if not exists academic_affinity_score numeric(5,2);
alter table potential_profiles add column if not exists track_lean numeric(5,2);
alter table potential_profiles add column if not exists track_reason text
  check (track_reason in ('khoa_cung', 'chenh_lech', 'chua_du_can_cu', 'chua_toi_hoc_ky_chot'));

alter table profile_snapshots add column if not exists recommended_track text
  check (recommended_track in ('VOCATIONAL_9PLUS', 'ACADEMIC_HIGH_SCHOOL', 'DUAL_EXPLORATION'));
alter table profile_snapshots add column if not exists vocational_affinity_score numeric(5,2);
alter table profile_snapshots add column if not exists academic_affinity_score numeric(5,2);
alter table profile_snapshots add column if not exists track_lean numeric(5,2);
alter table profile_snapshots add column if not exists track_reason text
  check (track_reason in ('khoa_cung', 'chenh_lech', 'chua_du_can_cu', 'chua_toi_hoc_ky_chot'));

-- 2-4) NOI DUNG -----------------------------------------------------------------
-- 2a) 8 nhom: ten / mo ta / nghe vi du moi (ma giu nguyen). Ung dung doc nhom tu code, bang domains de khop khoa ngoai + bao cao.
update domains set name = 'Khoa học, Kiểm nghiệm & Quan trắc', short_description = 'Thích tìm hiểu vì sao, đo đạc và thử nghiệm: đo độ chua của đất, kiểm tra nước sinh hoạt, theo dõi mưa nắng để báo lũ.', why_relevant = 'Xã nào cũng cần người biết kiểm tra đất, nước và thời tiết để phòng lũ quét, sạt lở và chọn cây trồng hợp đất.', sample_careers = array['Kỹ thuật viên kiểm nghiệm đất - nước', 'Kỹ thuật viên trắc địa', 'Quan trắc khí tượng - thủy văn', 'Nhà nghiên cứu', 'Kỹ sư môi trường']::text[], icon = '🔬' where code = 'KHOA_HOC_KHAM_PHA';
update domains set name = 'Điện, Điện mặt trời & Xe điện', short_description = 'Thích tháo lắp, đấu dây, sửa đồ điện: bóng đèn, quạt, ắc-quy, xe đạp điện, tấm pin mặt trời.', why_relevant = 'Nhiều bản còn thiếu điện ổn định; người biết lắp điện mặt trời, sửa xe điện có thể mở tiệm ngay tại nhà.', sample_careers = array['Thợ điện dân dụng', 'Lắp đặt điện mặt trời', 'Sửa chữa xe điện', 'Sửa chữa thiết bị điện tử', 'Kỹ sư điện - tự động hóa', 'Công nghệ thông tin']::text[], icon = '⚡' where code = 'KY_THUAT_CONG_NGHE';
update domains set name = 'Kỹ thuật Nông - Lâm nghiệp & Môi trường', short_description = 'Thích làm vườn, chăm rừng, nuôi con vật và tính toán chuyện nước tưới, sâu bệnh, mùa vụ.', why_relevant = 'Mùa khô thiếu nước, rừng dễ cháy: người biết chọn máy bơm, phòng cháy rừng, trồng cây chất lượng cao rất cần ở vùng cao.', sample_careers = array['Kỹ thuật viên nông nghiệp công nghệ cao', 'Kỹ thuật viên lâm nghiệp', 'Thú y', 'Khuyến nông', 'Kỹ sư nông lâm', 'Dự án môi trường']::text[], icon = '🌱' where code = 'NONG_LAM_NGU_MOI_TRUONG';
update domains set name = 'Thương mại Nông sản & Du lịch Bản địa', short_description = 'Thích tính tiền lời lỗ, bán hàng, giới thiệu đặc sản và đón khách du lịch về bản.', why_relevant = 'Nông sản, đặc sản và homestay của bản cần người biết tính vốn, bán hàng online và đón khách.', sample_careers = array['Bán hàng nông sản online', 'Homestay - du lịch cộng đồng', 'Hướng dẫn viên địa phương', 'Nấu ăn - ẩm thực địa phương', 'Kế toán hợp tác xã']::text[], icon = '🧺' where code = 'KINH_DOANH_DICH_VU';
update domains set name = 'Y tế, Điều dưỡng & Dược', short_description = 'Thích chăm sóc người ốm, tìm hiểu cơ thể, sơ cứu và các cây thuốc quanh bản.', why_relevant = 'Trạm y tế xã vùng cao luôn thiếu người. Muốn làm nghề y phải học hết THPT rồi học cao đẳng hoặc đại học.', sample_careers = array['Điều dưỡng', 'Bác sĩ', 'Dược sĩ', 'Hộ sinh', 'Kỹ thuật viên xét nghiệm']::text[], icon = '🩺' where code = 'SUC_KHOE_CONG_DONG';
update domains set name = 'Sân khấu, Ánh sáng & Đa phương tiện', short_description = 'Thích dàn dựng sân khấu, chỉnh âm thanh ánh sáng, quay và dựng video, vẽ, làm nhạc.', why_relevant = 'Lễ hội, đám cưới, sự kiện của xã và video quảng bá đặc sản đều cần người biết dựng sân khấu, quay dựng.', sample_careers = array['Kỹ thuật âm thanh - ánh sáng', 'Dựng sân khấu sự kiện', 'Quay dựng video', 'Thiết kế đồ họa', 'Truyền thông']::text[], icon = '🎬' where code = 'NGHE_THUAT_SANG_TAO';
update domains set name = 'Sư phạm, Giáo dục & Công tác xã hội', short_description = 'Thích giảng lại cho người khác hiểu, kèm em nhỏ học bài, kết nối và giúp đỡ mọi người trong bản.', why_relevant = 'Vùng cao rất cần thầy cô cắm bản. Muốn làm giáo viên phải học hết THPT rồi học cao đẳng hoặc đại học sư phạm.', sample_careers = array['Giáo viên mầm non', 'Giáo viên tiểu học - THCS', 'Công tác xã hội', 'Phiên dịch tiếng dân tộc', 'Thư viện']::text[], icon = '📚' where code = 'XA_HOI_GIAO_DUC_NHAN_VAN';
update domains set name = 'Xây dựng, Cơ khí & Nghề thủ công', short_description = 'Thích đo đạc, đóng, hàn, xây, làm mộc hoặc làm đồ thủ công truyền thống bằng đôi tay khéo léo.', why_relevant = 'Nhà cửa, kho, chuồng trại kiên cố chống sạt lở và các nghề mộc, hàn, dệt, đan lát luôn có việc ở địa phương.', sample_careers = array['Thợ xây - nề', 'Thợ hàn - cơ khí', 'Thợ mộc', 'Dệt - đan lát truyền thống', 'Kỹ sư xây dựng cầu đường']::text[], icon = '🧱' where code = 'THE_CHAT_THU_CONG';

