-- 3a) Hoat dong doi nghia (nhom moi): cho nghi, giu id cho nhat ky hoat dong cu.
update activities set active = false where id in ('act_kt_04', 'act_sk_03', 'act_nt_04', 'act_tc_01', 'act_tc_03', 'act_tc_04', 'act_kt_05', 'act_kt_06', 'act_tc_05');

-- 3b) Hoat dong moi (dung chung + theo hoc ky). mediaUrl = null: giao vien dan video quay THAT.
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_kt_07', 'KY_THUAT_CONG_NGHE', null, 'Tìm cầu dao (aptomat) nhà em', 'Cùng người lớn tìm cầu dao tổng của nhà và hỏi khi nào cần ngắt điện.', 4, array['Nhờ người lớn chỉ chỗ đặt cầu dao tổng.', 'Chỉ nhìn, không tự bật tắt, không chạm tay ướt.', 'Hỏi: khi nào cần ngắt cầu dao?']::text[], 'Cầu dao nhà em ở đâu? Em có biết khi nào cần ngắt điện không?', null, 'Ví dụ: Cầu dao nhà em ở cạnh cửa bếp. Bố bảo khi sửa ổ cắm hoặc có người bị điện giật thì phải ngắt cầu dao trước.', true, 'ALL', '[{"id":"act_kt_07_q1","prompt":"Ở cầu dao nhà em, thợ điện dân dụng làm việc chính gì?","options":["Ngắt điện trước khi sửa chữa","Sơn lại cầu dao","Đếm tiền điện"],"correct":0,"explanation":"Thợ điện luôn ngắt cầu dao trước khi sửa ổ cắm hay dây điện."},{"id":"act_kt_07_q2","prompt":"Khi tìm cầu dao cùng người lớn, em không được làm gì?","options":["Chạm tay ướt hoặc tự bật tắt","Nhìn và hỏi","Ghi lại vị trí"],"correct":0,"explanation":"Cầu dao là chỗ có điện, chỉ người lớn hoặc thợ điện mới thao tác."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_kt_08', 'KY_THUAT_CONG_NGHE', null, 'Sạc xe đạp điện thế nào cho an toàn?', 'Quan sát người lớn sạc xe đạp điện hoặc xe máy điện và ghi lại các điều cần chú ý.', 4, array['Xem người lớn cắm sạc xe điện.', 'Để ý chỗ đặt sạc: khô ráo, thoáng, xa đồ dễ cháy.', 'Hỏi: sạc bao lâu thì đầy?']::text[], 'Em thấy chỗ sạc xe nhà em đã an toàn chưa? Có gì cần sửa không?', null, 'Ví dụ: Nhà em sạc xe ở hiên, cạnh đống củi. Em đề nghị chuyển củi ra xa vì sạc qua đêm có thể nóng.', true, 'ALL', '[{"id":"act_kt_08_q1","prompt":"Người sửa xe điện hay dặn khách điều gì khi sạc xe?","options":["Sạc chỗ khô, thoáng, xa đồ dễ cháy","Sạc cạnh đống củi","Sạc dưới mưa"],"correct":0,"explanation":"Sạc lâu sinh nóng, đặt sai chỗ dễ gây cháy, nên thợ luôn dặn kỹ."},{"id":"act_kt_08_q2","prompt":"Việc kiểm tra ắc-quy và bộ sạc xe điện là công việc của ai?","options":["Thợ sửa chữa xe điện","Giáo viên","Người bán quần áo"],"correct":0,"explanation":"Thợ sửa xe điện kiểm tra ắc-quy, bộ sạc, động cơ cho xe chạy an toàn."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_kt_09', 'KY_THUAT_CONG_NGHE', 'KHOA_HOC_KHAM_PHA', 'Đồ điện nào tốn điện nhất?', 'Đếm các đồ dùng điện trong nhà, đọc số W trên nhãn và đoán cái nào tốn điện nhất.', 5, array['Liệt kê các đồ dùng điện trong nhà.', 'Tìm số W ghi trên nhãn (nhờ người lớn nếu khó).', 'Xếp từ tốn điện nhiều đến ít.']::text[], 'Đồ nào tốn điện nhất? Nhà em có thể tiết kiệm điện ở đâu?', null, 'Ví dụ: Nồi cơm điện 700W, quạt 45W, bóng đèn 9W. Nồi cơm tốn nhất, nhưng chỉ bật lúc nấu.', true, 'ALL', '[{"id":"act_kt_09_q1","prompt":"Đọc số W trên nhãn đồ điện giúp người thợ điện biết gì?","options":["Đồ đó dùng nhiều hay ít điện","Đồ đó màu gì","Đồ đó mua ở đâu"],"correct":0,"explanation":"Số W cho biết công suất; thợ điện dựa vào đó để chọn dây, ổ cắm phù hợp."},{"id":"act_kt_09_q2","prompt":"Ai thường tư vấn gia đình cách dùng điện tiết kiệm, an toàn?","options":["Thợ điện, kỹ sư điện","Người bán hoa","Thợ may"],"correct":0,"explanation":"Thợ điện và kỹ sư điện biết đồ nào tốn điện và cách dùng cho hợp lý."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_nl_07', 'NONG_LAM_NGU_MOI_TRUONG', null, 'Một luống rau cần bao nhiêu nước?', 'Đếm số gáo hoặc bình nước tưới một luống rau và tính cả tuần cần bao nhiêu.', 5, array['Phụ người lớn tưới một luống rau.', 'Đếm số gáo hoặc bình nước đã dùng.', 'Nhân lên 7 ngày, xem mùa khô có đủ nước không.']::text[], 'Mùa khô nhà em lấy nước tưới ở đâu? Có cách nào tiết kiệm nước không?', null, 'Ví dụ: Một luống cải cần 6 gáo mỗi chiều, cả tuần là 42 gáo. Phủ rơm lên luống thì đất giữ ẩm lâu hơn.', true, 'ALL', '[{"id":"act_nl_07_q1","prompt":"Tính lượng nước tưới cho cả mùa khô là việc của ai?","options":["Kỹ thuật viên nông nghiệp chất lượng cao","Thợ may","Người dẫn chương trình"],"correct":0,"explanation":"Kỹ thuật viên tính nước tưới để cây đủ nước mà không lãng phí khi mùa khô thiếu nước."},{"id":"act_nl_07_q2","prompt":"Mùa khô thiếu nước, người làm vườn thường làm gì để giữ ẩm cho luống rau?","options":["Phủ rơm, lá khô lên mặt luống","Tưới thật nhiều giữa trưa nắng","Bỏ không tưới"],"correct":0,"explanation":"Phủ rơm giảm nước bốc hơi, tưới sáng sớm hoặc chiều mát đỡ phí nước."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_kd_07', 'KINH_DOANH_DICH_VU', null, 'Nấu một món đặc sản và tính giá bán', 'Phụ nấu một món quen của quê em, ghi nguyên liệu và tính nếu bán cho khách thì giá bao nhiêu.', 5, array['Phụ người lớn nấu một món đặc sản đơn giản.', 'Ghi giá từng nguyên liệu.', 'Cộng lại, thêm tiền công để ra giá bán.']::text[], 'Món của em bán bao nhiêu thì có lời? Khách du lịch có thích món này không?', null, 'Ví dụ: Xôi ngũ sắc 4 suất hết 40.000đ nguyên liệu. Bán 15.000đ một suất thì lời 20.000đ.', true, 'ALL', '[{"id":"act_kd_07_q1","prompt":"Tính giá nguyên liệu để đặt giá bán món ăn là việc của ai?","options":["Chủ quán ăn, homestay","Thợ điện","Y tá"],"correct":0,"explanation":"Chủ quán và homestay phải tính chi phí để giá bán có lời mà khách vẫn chấp nhận."},{"id":"act_kd_07_q2","prompt":"Nấu ăn để bán cho khách, điều quan trọng nhất là gì?","options":["Sạch sẽ, an toàn thực phẩm","Nấu thật nhanh, không rửa","Dùng đồ ăn ôi cho rẻ"],"correct":0,"explanation":"Khách du lịch chỉ quay lại khi đồ ăn sạch, an toàn."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_sk_06', 'SUC_KHOE_CONG_DONG', 'NONG_LAM_NGU_MOI_TRUONG', 'Nhận biết một cây thuốc quanh nhà', 'Nhờ người lớn chỉ một cây thuốc nam quanh nhà và hỏi người ta dùng nó thế nào.', 4, array['Nhờ người lớn chỉ một cây thuốc quen.', 'Vẽ lá cây và ghi tên cây.', 'Hỏi cách dùng. Không tự hái, tự uống.']::text[], 'Cây thuốc em tìm được là cây gì? Vì sao không được tự ý dùng thuốc?', null, 'Ví dụ: Bà chỉ cây ngải cứu, người ta hay dùng khi đau đầu. Bà dặn cây thuốc cũng phải hỏi y sĩ trước khi dùng.', true, 'ALL', '[{"id":"act_sk_06_q1","prompt":"Ai nghiên cứu cây thuốc và chế biến thành thuốc an toàn?","options":["Dược sĩ, người làm y học cổ truyền","Thợ xây","Người bán vé"],"correct":0,"explanation":"Dược sĩ và y học cổ truyền biết cây nào làm thuốc, dùng liều bao nhiêu cho an toàn."},{"id":"act_sk_06_q2","prompt":"Thấy một cây được bảo là cây thuốc, em có nên tự hái uống không?","options":["Không, phải hỏi y sĩ, dược sĩ","Có, uống càng nhiều càng tốt","Có, nếu lá đẹp"],"correct":0,"explanation":"Nhiều cây giống nhau, có cây độc; phải hỏi người có chuyên môn."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_nt_07', 'NGHE_THUAT_SANG_TAO', null, 'Chiếu đèn pin cho một sân khấu tí hon', 'Đặt một đồ vật lên bàn, chiếu đèn pin từ nhiều phía và xem bóng đổ thay đổi thế nào.', 4, array['Đặt một đồ vật lên bàn, tắt bớt đèn.', 'Chiếu đèn pin từ trước, bên cạnh, rồi từ dưới lên.', 'Chọn hướng chiếu đẹp nhất.']::text[], 'Chiếu từ hướng nào thì đồ vật trông đẹp hoặc đáng sợ nhất?', null, 'Ví dụ: Chiếu từ dưới lên, con gà gỗ trông như ma. Chiếu chéo từ bên cạnh thì thấy rõ vân gỗ.', true, 'ALL', '[{"id":"act_nt_07_q1","prompt":"Chiếu đèn từ nhiều hướng cho đẹp là việc của ai?","options":["Kỹ thuật viên ánh sáng sân khấu","Kế toán","Người trồng rừng"],"correct":0,"explanation":"Kỹ thuật viên ánh sáng chọn hướng, màu đèn để sân khấu đẹp và rõ người diễn."},{"id":"act_nt_07_q2","prompt":"Dựng đèn sân khấu thật, điều an toàn quan trọng nhất là gì?","options":["Dây điện gọn, chắc, có thợ điện kiểm tra","Để dây lộn xộn dưới chân","Treo đèn bằng dây buộc tạm"],"correct":0,"explanation":"Sân khấu đông người, dây điện và đèn phải chắc chắn, an toàn."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_nt_08', 'NGHE_THUAT_SANG_TAO', 'KINH_DOANH_DICH_VU', 'Quay video 30 giây giới thiệu đặc sản', 'Dùng điện thoại quay một đoạn ngắn giới thiệu một đặc sản hoặc cảnh đẹp của bản.', 5, array['Chọn một đặc sản hoặc cảnh đẹp.', 'Viết 2 câu giới thiệu.', 'Quay 30 giây, đứng quay lưng về phía ánh sáng.']::text[], 'Video của em có rõ không? Lần sau em muốn quay khác chỗ nào?', null, 'Ví dụ: Em quay chè Shan tuyết: cận lá chè, rồi cảnh đồi chè buổi sáng, nói 2 câu về vị chè.', true, 'ALL', '[{"id":"act_nt_08_q1","prompt":"Quay video giới thiệu đặc sản của bản là công việc của ai?","options":["Người quay dựng video, làm truyền thông","Thợ hàn","Y tá"],"correct":0,"explanation":"Người quay dựng video làm phim ngắn quảng bá sản phẩm, du lịch địa phương."},{"id":"act_nt_08_q2","prompt":"Quay video, đứng thế nào thì hình sáng, rõ?","options":["Lưng quay về phía ánh sáng","Quay thẳng vào mặt trời","Quay trong chỗ tối"],"correct":0,"explanation":"Ánh sáng chiếu vào vật cần quay thì hình rõ; ngược sáng thì vật bị tối."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_tc_07', 'THE_CHAT_THU_CONG', null, 'Đo và vẽ sơ đồ gian bếp', 'Đo gian bếp bằng bước chân hoặc sợi dây rồi vẽ sơ đồ nhìn từ trên xuống.', 5, array['Đo chiều dài, chiều rộng gian bếp bằng bước chân.', 'Vẽ hình chữ nhật theo tỉ lệ trên giấy.', 'Đánh dấu cửa, bếp, chạn bát.']::text[], 'Nếu được sửa lại gian bếp, em muốn đặt bếp ở đâu cho thoáng và an toàn?', null, 'Ví dụ: Bếp dài 6 bước, rộng 4 bước. Em vẽ 6 ô x 4 ô, bếp củi ở góc trong, cửa ở giữa tường dài.', true, 'ALL', '[{"id":"act_tc_07_q1","prompt":"Đo phòng rồi vẽ sơ đồ nhìn từ trên xuống giống việc của ai?","options":["Thợ xây, kỹ sư xây dựng","Người bán hàng","Y tá"],"correct":0,"explanation":"Thợ xây và kỹ sư đo đạc, vẽ mặt bằng trước khi xây hoặc sửa nhà."},{"id":"act_tc_07_q2","prompt":"Vì sao thợ xây cần bản vẽ có kích thước?","options":["Để tính vật liệu và xây đúng","Để treo cho đẹp","Không cần, xây bừa được"],"correct":0,"explanation":"Có kích thước thì biết cần bao nhiêu gạch, xi măng và xây đúng chỗ."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_tc_08', 'THE_CHAT_THU_CONG', 'KHOA_HOC_KHAM_PHA', 'Dựng cây cầu bằng que tre', 'Dùng que tre hoặc đũa, dây buộc dựng một cây cầu nhỏ đỡ được một quyển vở.', 5, array['Buộc que thành các hình tam giác.', 'Ghép thành cây cầu bắc qua hai chồng sách.', 'Đặt quyển vở lên xem cầu có đứng vững không.']::text[], 'Cầu của em có vững không? Hình tam giác giúp gì cho cây cầu?', null, 'Ví dụ: Cầu làm bằng hình vuông bị xô lệch. Em buộc thêm que chéo thành tam giác thì cầu đỡ được 2 quyển vở.', true, 'ALL', '[{"id":"act_tc_08_q1","prompt":"Ai thiết kế cầu cho chắc, chịu được xe đi qua?","options":["Kỹ sư cầu đường","Người bán rau","Giáo viên mầm non"],"correct":0,"explanation":"Kỹ sư cầu đường tính toán hình dạng, vật liệu để cầu chịu được sức nặng."},{"id":"act_tc_08_q2","prompt":"Vì sao thợ xây hay dùng thanh chéo hình tam giác?","options":["Tam giác giữ khung không bị xô lệch","Cho đẹp mắt","Để tốn thêm vật liệu"],"correct":0,"explanation":"Khung tam giác cứng, không bị méo như hình vuông khi có lực đè."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_tc_09', 'THE_CHAT_THU_CONG', 'NONG_LAM_NGU_MOI_TRUONG', 'Kiểm tra bờ rào, tường đất sau mưa', 'Đi một vòng quanh nhà cùng người lớn, tìm chỗ tường đất, bờ kè có vết nứt hoặc sụt.', 4, array['Đi cùng người lớn, không lại gần mép taluy.', 'Tìm vết nứt, chỗ đất sụt, cọc rào nghiêng.', 'Vẽ lại vị trí và báo người lớn.']::text[], 'Em tìm thấy chỗ nào yếu? Nên gia cố bằng cách nào?', null, 'Ví dụ: Bờ đất sau chuồng gà có vết nứt dài một gang tay. Bố bảo cần đóng cọc và trồng cỏ giữ đất.', true, 'ALL', '[{"id":"act_tc_09_q1","prompt":"Kiểm tra tường, bờ kè có nứt sau mưa là việc của ai?","options":["Thợ xây, kỹ thuật viên xây dựng","Người quay video","Người bán hàng"],"correct":0,"explanation":"Họ kiểm tra công trình sau mưa lũ để gia cố kịp thời, tránh sạt lở."},{"id":"act_tc_09_q2","prompt":"Khi đi kiểm tra bờ đất sau mưa, em phải chú ý gì?","options":["Đi cùng người lớn, tránh xa mép taluy","Đứng sát mép nhìn xuống","Đi một mình ban đêm"],"correct":0,"explanation":"Đất sau mưa dễ sụt; người làm xây dựng cũng không đứng sát mép."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_tc_10', 'THE_CHAT_THU_CONG', null, 'Đóng đinh, bắt vít đúng cách', 'Nhờ người lớn chỉ cách cầm búa đóng đinh hoặc dùng tua vít bắt vít vào miếng gỗ.', 5, array['Nhờ người lớn làm mẫu trước.', 'Giữ đinh bằng kẹp hoặc giấy gấp, không giữ bằng tay.', 'Đóng 2 cây đinh vào miếng gỗ vụn.']::text[], 'Đinh của em có thẳng không? Làm thế nào để không đập vào tay?', null, 'Ví dụ: Cây đầu tiên em đóng bị cong. Cây thứ hai em gõ nhẹ cho đinh đứng rồi mới đóng mạnh thì thẳng.', true, 'ALL', '[{"id":"act_tc_10_q1","prompt":"Đóng đinh, bắt vít vào gỗ là việc hằng ngày của ai?","options":["Thợ mộc","Dược sĩ","Người bán vé"],"correct":0,"explanation":"Thợ mộc đóng đinh, bắt vít để làm bàn ghế, cửa, kèo nhà."},{"id":"act_tc_10_q2","prompt":"Khi đóng đinh, cách giữ đinh an toàn là gì?","options":["Giữ đinh bằng kẹp hoặc giấy gấp","Giữ bằng ngón tay sát đầu búa","Nhắm mắt khi đóng"],"correct":0,"explanation":"Kẹp hoặc giấy gấp giúp ngón tay ở xa búa, không bị đập vào tay."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_tc_11', 'THE_CHAT_THU_CONG', 'KHOA_HOC_KHAM_PHA', 'Nặn thử viên gạch đất', 'Trộn đất sét với cát hoặc rơm, nặn 2 viên gạch nhỏ, phơi khô rồi so viên nào chắc hơn.', 5, array['Viên 1: chỉ đất sét. Viên 2: đất sét trộn rơm.', 'Nặn hai viên to bằng bao diêm.', 'Phơi vài ngày rồi bẻ thử.']::text[], 'Viên nào chắc hơn? Vì sao ngày xưa người ta trộn rơm vào đất trình tường?', null, 'Ví dụ: Viên chỉ có đất sét nứt khi khô. Viên trộn rơm ít nứt và khó bẻ hơn.', true, 'ALL', '[{"id":"act_tc_11_q1","prompt":"Thử độ chắc của gạch, vữa trước khi xây là việc của ai?","options":["Thợ xây, kỹ thuật viên vật liệu","Người bán quần áo","Y tá"],"correct":0,"explanation":"Họ thử vật liệu trước để nhà xây chắc, không nứt."},{"id":"act_tc_11_q2","prompt":"Trộn rơm vào đất làm gạch có tác dụng gì?","options":["Giúp gạch ít nứt, chắc hơn","Cho gạch thơm","Không có tác dụng"],"correct":0,"explanation":"Sợi rơm giữ đất lại với nhau, gạch khô ít nứt hơn."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h1_01', 'THE_CHAT_THU_CONG', null, 'Vẽ 3 hình chiếu của một hộp diêm', 'Nhìn một hộp diêm hoặc viên gạch từ trước, từ trên, từ bên cạnh và vẽ 3 hình.', 5, array['Đặt hộp diêm lên bàn.', 'Vẽ hình nhìn từ trước, từ trên, từ bên trái.', 'Ghi kích thước đo bằng thước.']::text[], 'Nhìn 3 hình em vẽ, người khác có làm lại được đúng vật đó không?', null, 'Ví dụ: Nhìn từ trước là hình chữ nhật 5 x 1,5 cm, nhìn từ trên là hình chữ nhật 5 x 3,5 cm.', true, 'G8_HK1', '[{"id":"act_g8h1_01_q1","prompt":"Vẽ hình chiếu có kích thước để người khác làm theo là việc của ai?","options":["Người vẽ kỹ thuật, kỹ sư","Người bán hàng","Y tá"],"correct":0,"explanation":"Người vẽ kỹ thuật làm bản vẽ để thợ đọc và làm ra đúng vật."},{"id":"act_g8h1_01_q2","prompt":"Thợ mộc, thợ cơ khí dùng bản vẽ kỹ thuật để làm gì?","options":["Làm ra vật đúng hình, đúng cỡ","Để trang trí xưởng","Không dùng đến"],"correct":0,"explanation":"Đọc bản vẽ, thợ biết vật dài, rộng, cao bao nhiêu để cắt, ghép đúng."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h1_02', 'THE_CHAT_THU_CONG', 'KHOA_HOC_KHAM_PHA', 'Đồ vật này làm bằng vật liệu gì?', 'Tìm 5 đồ dùng trong nhà, đoán làm bằng sắt, nhôm, gỗ hay nhựa và thử bằng nam châm.', 4, array['Chọn 5 đồ: dao, nồi, ghế, xô, cuốc.', 'Đoán vật liệu của từng thứ.', 'Đưa nam châm lại gần: sắt thì hút, nhôm thì không.']::text[], 'Vì sao lưỡi cuốc làm bằng thép còn cán cuốc làm bằng gỗ?', null, 'Ví dụ: Lưỡi dao bị nam châm hút nên là thép. Nồi nhôm không hút. Cán dao bằng gỗ cho đỡ nóng tay.', true, 'G8_HK1', '[{"id":"act_g8h1_02_q1","prompt":"Chọn đúng vật liệu thép, gỗ, nhựa cho từng bộ phận là việc của ai?","options":["Thợ cơ khí, thợ mộc","Người bán hàng","Giáo viên"],"correct":0,"explanation":"Thợ cơ khí và thợ mộc chọn vật liệu hợp với việc: chịu lực, chống nóng, nhẹ."},{"id":"act_g8h1_02_q2","prompt":"Vì sao cán dao, cán nồi thường làm bằng gỗ hoặc nhựa?","options":["Đỡ nóng tay, cầm chắc","Cho nặng hơn","Vì rẻ nhất"],"correct":0,"explanation":"Gỗ và nhựa dẫn nhiệt kém nên cầm không bị bỏng tay."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h1_03', 'KY_THUAT_CONG_NGHE', 'THE_CHAT_THU_CONG', 'Xích xe đạp truyền chuyển động thế nào?', 'Quay bàn đạp một chiếc xe đạp dựng chân chống, đếm xem bánh sau quay mấy vòng.', 4, array['Dựng xe đạp chắc chắn, có người lớn ở cạnh.', 'Quay bàn đạp đúng 1 vòng bằng tay.', 'Đếm bánh sau quay được mấy vòng.']::text[], 'Vì sao đĩa to, líp nhỏ thì bánh xe quay nhanh hơn bàn đạp?', null, 'Ví dụ: Quay bàn đạp 1 vòng thì bánh sau quay gần 3 vòng. Xe đạp điện cũng dùng xích như vậy, nhưng có thêm động cơ.', true, 'G8_HK1', '[{"id":"act_g8h1_03_q1","prompt":"Ai kiểm tra xích, líp, động cơ cho xe đạp điện, xe máy điện?","options":["Thợ sửa chữa xe điện","Y tá","Người bán vải"],"correct":0,"explanation":"Thợ sửa xe điện kiểm tra cả bộ truyền động xích và động cơ điện."},{"id":"act_g8h1_03_q2","prompt":"Khi quay bàn đạp xe đạp để quan sát, điều an toàn là gì?","options":["Dựng xe chắc, không để tay vào xích","Thò ngón tay vào xích","Quay thật nhanh"],"correct":0,"explanation":"Xích và líp đang quay dễ kẹp tay."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h1_04', 'KHOA_HOC_KHAM_PHA', 'NONG_LAM_NGU_MOI_TRUONG', 'Đất nhà em có sủi bọt với giấm không?', 'Nhỏ vài giọt giấm vào hai mẫu đất khác nhau xem mẫu nào sủi bọt.', 4, array['Lấy 2 thìa đất ở 2 chỗ khác nhau.', 'Nhỏ vài giọt giấm lên mỗi mẫu.', 'Đất sủi bọt là có đá vôi, ít chua.']::text[], 'Mẫu đất nào sủi bọt? Theo em đất đó hợp trồng cây gì?', null, 'Ví dụ: Đất chân núi đá sủi bọt nhẹ, đất ruộng không sủi. Người làm kiểm nghiệm đất dùng máy đo độ chua chính xác hơn.', true, 'G8_HK1', '[{"id":"act_g8h1_04_q1","prompt":"Kiểm tra đất chua hay không để chọn cây là việc của ai?","options":["Kỹ thuật viên kiểm nghiệm đất","Thợ điện","Người dẫn chương trình"],"correct":0,"explanation":"Kỹ thuật viên kiểm nghiệm đo độ chua của đất để khuyên trồng cây hợp đất."},{"id":"act_g8h1_04_q2","prompt":"Làm thí nghiệm với giấm và đất xong, em nên làm gì?","options":["Rửa tay, dọn dẹp sạch","Nếm thử đất","Đổ giấm vào mắt"],"correct":0,"explanation":"Người làm kiểm nghiệm luôn dọn sạch và rửa tay sau thí nghiệm."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h2_01', 'KY_THUAT_CONG_NGHE', null, 'Vẽ sơ đồ mạch của đèn pin', 'Mở nắp một chiếc đèn pin dùng pin, xem pin, công tắc, bóng nối với nhau ra sao rồi vẽ lại.', 4, array['Mở nắp đèn pin, lấy pin ra xem.', 'Tìm đường đi: pin, lò xo, công tắc, bóng.', 'Vẽ sơ đồ mạch kín.']::text[], 'Vì sao bấm công tắc thì đèn tắt? Mạch hở là gì?', null, 'Ví dụ: Pin nối lò xo, lò xo nối công tắc, công tắc nối bóng. Bấm tắt là công tắc làm hở mạch.', true, 'G8_HK2', '[{"id":"act_g8h2_01_q1","prompt":"Vẽ sơ đồ mạch điện để tìm chỗ hỏng là việc của ai?","options":["Thợ điện, thợ sửa thiết bị điện tử","Người bán hàng","Thợ may"],"correct":0,"explanation":"Thợ điện dựa vào sơ đồ mạch để biết dòng điện đi đâu, đứt ở đâu."},{"id":"act_g8h2_01_q2","prompt":"Thợ điện tập với mạch nào trước khi làm điện trong nhà?","options":["Mạch pin nhỏ, điện áp thấp","Ổ điện đang có dòng","Dây điện ngoài cột"],"correct":0,"explanation":"Mạch pin nhỏ an toàn để tập; điện trong nhà rất nguy hiểm."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h2_02', 'KY_THUAT_CONG_NGHE', 'SUC_KHOE_CONG_DONG', 'Săn lỗi an toàn điện trong nhà', 'Đi một vòng trong nhà tìm chỗ có thể gây điện giật và báo người lớn. Chỉ nhìn, không chạm.', 4, array['Tìm dây điện hở, ổ cắm lỏng, ổ gần nước.', 'Không chạm vào chỗ nghi có điện.', 'Ghi lại và báo người lớn.']::text[], 'Em tìm thấy lỗi nào? Thợ điện sẽ sửa lỗi đó thế nào?', null, 'Ví dụ: Dây quạt bị chuột cắn hở lõi đồng. Em báo bố, bố rút điện rồi quấn băng dính cách điện.', true, 'G8_HK2', '[{"id":"act_g8h2_02_q1","prompt":"Ai sửa dây điện hở, ổ cắm lỏng trong nhà?","options":["Thợ điện dân dụng","Người bán rau","Giáo viên"],"correct":0,"explanation":"Thợ điện dân dụng ngắt điện rồi thay dây, siết ổ cắm cho an toàn."},{"id":"act_g8h2_02_q2","prompt":"Thấy dây điện bị hở, em nên làm gì?","options":["Không chạm, báo người lớn","Lấy tay giữ lại","Quấn bằng lá cây"],"correct":0,"explanation":"Dây hở có thể làm điện giật; chỉ người lớn hoặc thợ điện xử lý."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h2_03', 'THE_CHAT_THU_CONG', null, 'Thiết kế một cái giá phơi dép', 'Phác thảo một cái giá phơi dép bằng tre hoặc gỗ cho cả nhà, có ghi kích thước.', 5, array['Đếm số đôi dép của cả nhà.', 'Vẽ giá phơi, ghi chiều dài, chiều cao.', 'Ghi vật liệu cần dùng.']::text[], 'Thiết kế của em cần bao nhiêu thanh tre? Ai trong nhà có thể giúp em làm?', null, 'Ví dụ: Nhà 5 người, mỗi người 2 đôi. Giá 3 tầng, mỗi tầng dài 80 cm, cần 4 cọc và 6 thanh ngang.', true, 'G8_HK2', '[{"id":"act_g8h2_03_q1","prompt":"Phác thảo đồ vật, ghi kích thước, vật liệu là việc của ai?","options":["Người thiết kế kỹ thuật, thợ mộc","Y tá","Người bán hàng"],"correct":0,"explanation":"Người thiết kế tính trước kích thước, vật liệu để làm ra đồ dùng hợp nhu cầu."},{"id":"act_g8h2_03_q2","prompt":"Trước khi thiết kế, người thiết kế cần biết gì?","options":["Ai dùng và dùng để làm gì","Màu sơn đẹp nhất","Không cần biết gì"],"correct":0,"explanation":"Biết người dùng cần gì thì đồ làm ra mới vừa và tiện."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g8h2_04', 'SUC_KHOE_CONG_DONG', 'KY_THUAT_CONG_NGHE', 'Thấy người bị điện giật, làm gì trước?', 'Tập nói to 3 việc đầu tiên khi thấy người bị điện giật, cùng người lớn hoặc bạn.', 3, array['Việc 1: ngắt cầu dao hoặc rút phích cắm.', 'Việc 2: dùng que khô tách dây điện, không chạm tay.', 'Việc 3: gọi người lớn và gọi 115.']::text[], 'Vì sao không được kéo người bị điện giật bằng tay không?', null, 'Ví dụ: Em và bạn đóng vai. Bạn nói ''cứu'', em hô ''ngắt cầu dao trước'', rồi cầm que tre khô giả vờ gạt dây.', true, 'G8_HK2', '[{"id":"act_g8h2_04_q1","prompt":"Ai được học kỹ cách cứu người bị điện giật?","options":["Thợ điện, nhân viên y tế","Người bán hàng","Người quay video"],"correct":0,"explanation":"Thợ điện và nhân viên y tế đều phải biết sơ cứu tai nạn điện."},{"id":"act_g8h2_04_q2","prompt":"Thấy người bị điện giật, việc đầu tiên là gì?","options":["Ngắt nguồn điện","Kéo người đó bằng tay","Đổ nước vào người đó"],"correct":0,"explanation":"Phải ngắt điện trước; chạm vào người đang bị giật thì mình cũng bị giật."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h1_01', 'KY_THUAT_CONG_NGHE', null, 'Lần theo đường điện trong nhà', 'Nhìn đường dây điện từ công tơ vào cầu dao, ổ cắm, bóng đèn rồi vẽ sơ đồ. Chỉ nhìn, không chạm.', 5, array['Tìm công tơ điện và cầu dao.', 'Nhìn dây đi tới ổ cắm, công tắc, bóng đèn.', 'Vẽ sơ đồ mạng điện của nhà em.']::text[], 'Nếu lắp điện cho nhà mới, em muốn đặt ổ cắm ở đâu cho tiện và an toàn?', null, 'Ví dụ: Công tơ ở cột ngoài ngõ, dây vào cầu dao trong nhà, chia ra 3 bóng đèn và 2 ổ cắm.', true, 'G9_HK1', '[{"id":"act_g9h1_01_q1","prompt":"Lắp đường dây từ công tơ đến ổ cắm, bóng đèn là việc của ai?","options":["Thợ điện dân dụng","Thợ may","Người bán hàng"],"correct":0,"explanation":"Thợ điện dân dụng lắp mạng điện trong nhà theo sơ đồ, đúng an toàn."},{"id":"act_g9h1_01_q2","prompt":"Khi quan sát đường điện trong nhà, em không được làm gì?","options":["Chạm vào dây, mở ổ cắm","Nhìn và vẽ lại","Hỏi người lớn"],"correct":0,"explanation":"Chỉ quan sát và vẽ; mở hay chạm dây điện là việc của thợ điện."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h1_02', 'NONG_LAM_NGU_MOI_TRUONG', 'KY_THUAT_CONG_NGHE', 'Chọn máy bơm cho vườn nhà em', 'Ước lượng vườn rộng bao nhiêu, nguồn nước xa và thấp bao nhiêu, rồi hỏi người lớn nên mua bơm to hay nhỏ.', 5, array['Đếm bước chân đo vườn.', 'Ước lượng nguồn nước xa và thấp hơn vườn bao nhiêu.', 'Hỏi người lớn: bơm to hay nhỏ, vì sao?']::text[], 'Mua bơm quá to hoặc quá nhỏ thì có hại gì?', null, 'Ví dụ: Vườn 20 x 15 bước, suối thấp hơn vườn khoảng 5 m. Chú bán bơm bảo bơm nhỏ là đủ, đỡ tốn điện.', true, 'G9_HK1', '[{"id":"act_g9h1_02_q1","prompt":"Tư vấn chọn máy bơm hợp với vườn và nguồn nước là việc của ai?","options":["Kỹ thuật viên nông nghiệp, thợ điện","Giáo viên văn","Người quay video"],"correct":0,"explanation":"Họ tính diện tích vườn, độ cao nguồn nước để chọn bơm vừa đủ, đỡ tốn điện."},{"id":"act_g9h1_02_q2","prompt":"Mua máy bơm quá to so với vườn thì sao?","options":["Tốn tiền, tốn điện vô ích","Cây lớn nhanh hơn","Không sao cả"],"correct":0,"explanation":"Bơm vừa đủ là tiết kiệm nhất; quá to thì phí tiền mua và tiền điện."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h1_03', 'NONG_LAM_NGU_MOI_TRUONG', null, 'Tìm nguy cơ cháy rừng quanh bản', 'Quan sát quanh bản xem chỗ nào nhiều lá khô, chỗ nào hay đốt nương, rồi vẽ đường băng cản lửa.', 5, array['Nhìn từ xa, không vào rừng một mình.', 'Đánh dấu chỗ lá khô, chỗ đốt nương.', 'Vẽ một đường băng trống ngăn lửa lan.']::text[], 'Mùa khô, bản em có thể làm gì để rừng không bị cháy?', null, 'Ví dụ: Sườn đồi sau trường đầy lá thông khô, sát nương ngô. Em vẽ đường băng phát sạch rộng 10 m ở giữa.', true, 'G9_HK1', '[{"id":"act_g9h1_03_q1","prompt":"Theo dõi, phòng chống cháy rừng mùa khô là việc của ai?","options":["Kiểm lâm, kỹ thuật viên lâm nghiệp","Người bán hàng","Thợ may"],"correct":0,"explanation":"Kiểm lâm và kỹ thuật viên lâm nghiệp tuần tra, làm đường băng cản lửa mùa khô."},{"id":"act_g9h1_03_q2","prompt":"Đường băng cản lửa trong rừng có tác dụng gì?","options":["Ngăn lửa lan sang chỗ khác","Làm đường cho xe chạy","Trang trí rừng"],"correct":0,"explanation":"Dải đất trống không có lá khô nên lửa không cháy lan qua được."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h1_04', 'KY_THUAT_CONG_NGHE', 'KHOA_HOC_KHAM_PHA', 'Quan sát một tấm pin mặt trời', 'Tìm một tấm pin mặt trời hoặc đèn năng lượng mặt trời, xem hướng đặt và hỏi người dùng nó chạy được gì.', 4, array['Tìm tấm pin ở nhà, trường hoặc đèn đường.', 'Xem tấm pin quay về hướng nào, có bụi không.', 'Hỏi: buổi tối dùng điện từ đâu?']::text[], 'Bản em thiếu điện thì pin mặt trời giúp được gì? Ai sẽ lắp và sửa nó?', null, 'Ví dụ: Đèn đường đầu bản có tấm pin nhỏ quay về phía nam. Ban ngày sạc vào bình, tối đèn tự sáng.', true, 'G9_HK1', '[{"id":"act_g9h1_04_q1","prompt":"Lắp tấm pin mặt trời cho nhà dân là công việc của ai?","options":["Thợ lắp đặt điện mặt trời","Y tá","Người bán quần áo"],"correct":0,"explanation":"Thợ lắp điện mặt trời chọn hướng đặt pin, đấu dây và lắp bình lưu điện."},{"id":"act_g9h1_04_q2","prompt":"Tấm pin mặt trời cần gì để cho nhiều điện?","options":["Đủ nắng, mặt pin sạch bụi","Đặt trong bóng râm","Phủ bạt kín"],"correct":0,"explanation":"Pin nhận ánh nắng càng nhiều, mặt pin càng sạch thì càng ra nhiều điện."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h2_01', 'KY_THUAT_CONG_NGHE', null, 'Hỏi người sửa xe điện, thợ điện về nghề', 'Hỏi một người sửa xe điện hoặc thợ điện 3 câu: học ở đâu, học mấy năm, một ngày làm gì.', 5, array['Chọn một người làm nghề điện em quen.', 'Hỏi: học ở đâu, mấy năm, tốn bao nhiêu?', 'Hỏi: một ngày làm những việc gì?']::text[], 'Nghề này học sau lớp 9 được không? Em có muốn thử không?', null, 'Ví dụ: Chú sửa xe điện học trung cấp nghề ở tỉnh 1 năm rưỡi. Mỗi ngày chú thay ắc-quy, sửa sạc, kiểm tra động cơ.', true, 'G9_HK2', '[{"id":"act_g9h2_01_q1","prompt":"Nghề sửa xe điện, thợ điện có thể học ngay sau lớp 9 không?","options":["Có, ở trường trung cấp, cao đẳng nghề","Không, phải học đại học","Không ai dạy nghề này"],"correct":0,"explanation":"Trường trung cấp, cao đẳng nghề trong tỉnh nhận học sinh hết lớp 9 học nghề điện."},{"id":"act_g9h2_01_q2","prompt":"Muốn hiểu thật một nghề, cách tốt nhất là gì?","options":["Hỏi trực tiếp người đang làm nghề","Đoán theo tin đồn","Chọn nghề bạn thân chọn"],"correct":0,"explanation":"Người làm nghề kể rõ công việc hằng ngày, đường học và cái khó của nghề."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h2_02', 'SUC_KHOE_CONG_DONG', null, 'Hỏi một y sĩ, điều dưỡng về con đường học', 'Hỏi một người làm ở trạm y tế: phải học hết lớp mấy, học trường gì, mấy năm.', 5, array['Gặp một người làm ở trạm y tế xã.', 'Hỏi: phải học hết THPT không, học trường nào?', 'Hỏi: điều gì khó nhất trong nghề?']::text[], 'Muốn làm nghề y em cần chuẩn bị gì từ bây giờ?', null, 'Ví dụ: Cô điều dưỡng học hết lớp 12 rồi học cao đẳng y 3 năm. Cô bảo cần học tốt Sinh và Hóa.', true, 'G9_HK2', '[{"id":"act_g9h2_02_q1","prompt":"Muốn làm điều dưỡng, y sĩ thì phải học thế nào?","options":["Hết THPT rồi học cao đẳng, đại học y","Học nghề 3 tháng sau lớp 9","Không cần học"],"correct":0,"explanation":"Nghề y bắt buộc học hết THPT rồi học trường y."},{"id":"act_g9h2_02_q2","prompt":"Học sinh muốn theo nghề y nên chú ý học tốt môn nào?","options":["Sinh học, Hóa học","Chỉ Thể dục","Không môn nào"],"correct":0,"explanation":"Kiến thức Sinh và Hóa là nền để học về cơ thể và thuốc."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h2_03', 'NONG_LAM_NGU_MOI_TRUONG', 'KINH_DOANH_DICH_VU', 'Hỏi người trồng cây giỏi trong bản', 'Hỏi một người trồng cây, nuôi con hoặc cán bộ khuyến nông: học nghề ở đâu, thu nhập từ đâu.', 5, array['Chọn một người làm nông giỏi hoặc cán bộ khuyến nông.', 'Hỏi: học kỹ thuật ở đâu, mấy năm?', 'Hỏi: mấy năm thì cây cho thu hoạch, bán được?']::text[], 'Học nghề nông lâm sau lớp 9 thì em có thể làm gì ở bản mình?', null, 'Ví dụ: Chú trồng quế học lớp kỹ thuật 3 tháng ở huyện. Quế trồng 10 năm mới bóc vỏ bán được.', true, 'G9_HK2', '[{"id":"act_g9h2_03_q1","prompt":"Cán bộ khuyến nông làm công việc chính gì?","options":["Hướng dẫn bà con kỹ thuật trồng trọt, chăn nuôi","Bán điện thoại","Sửa xe máy"],"correct":0,"explanation":"Cán bộ khuyến nông đến từng bản dạy cách trồng, nuôi cho năng suất cao."},{"id":"act_g9h2_03_q2","prompt":"Trồng cây lấy gỗ, cây quế thì bao lâu mới bán được?","options":["Nhiều năm, phải tính trước","Ngay tháng sau","Một tuần"],"correct":0,"explanation":"Cây lâu năm cần nhiều năm mới thu hoạch, nên phải tính vốn và thời gian trước."}]'::jsonb) on conflict (id) do nothing;
insert into activities (id, domain, secondary_domain, title, description, duration_minutes, instructions, reflection_prompt, media_url, example, active, curriculum_term, quiz) values ('act_g9h2_04', 'THE_CHAT_THU_CONG', null, 'Hỏi thợ xây, thợ mộc trong bản về nghề', 'Hỏi một thợ xây, thợ hàn hoặc thợ mộc: học nghề ở đâu, bao lâu, việc nào khó nhất.', 5, array['Chọn một người làm xây dựng, hàn hoặc mộc.', 'Hỏi: học ở trường hay theo thợ cả, mấy năm?', 'Hỏi: muốn tay nghề cao, lương cao cần gì?']::text[], 'Nghề này cần học tiếp THPT hay học nghề sau lớp 9 cũng được?', null, 'Ví dụ: Chú thợ hàn học cao đẳng nghề 2 năm, có chứng chỉ nên nhận được việc ở công trình lớn, lương cao hơn.', true, 'G9_HK2', '[{"id":"act_g9h2_04_q1","prompt":"Thợ hàn, thợ xây có chứng chỉ nghề thường được lợi gì?","options":["Dễ nhận việc lớn, lương cao hơn","Không có lợi gì","Không phải làm việc"],"correct":0,"explanation":"Chứng chỉ chứng minh tay nghề, giúp nhận việc ở công trình lớn, thu nhập cao hơn."},{"id":"act_g9h2_04_q2","prompt":"Muốn thành thợ có tay nghề cao, cần gì?","options":["Học bài bản và luyện tập nhiều năm","Chỉ cần sức khỏe","Chỉ học vài ngày"],"correct":0,"explanation":"Tay nghề cao đến từ học có hệ thống và làm thật nhiều."}]'::jsonb) on conflict (id) do nothing;

-- 3c) Quiz nhan biet nghe + cac buoc rut gon cho hoat dong cu - CHI khi giao vien chua sua (gia tri van la ban soan san cu).
update activities set quiz = '[{"id":"act_kh_01_q1","prompt":"So sánh giọt nước trên nhiều loại lá giống công việc của ai nhất?","options":["Người làm thí nghiệm, kiểm nghiệm","Người bán hàng","Thợ xây"],"correct":0,"explanation":"Người làm kiểm nghiệm cũng so sánh nhiều mẫu, giữ mọi thứ giống nhau, rồi ghi kết quả."},{"id":"act_kh_01_q2","prompt":"Muốn so sánh công bằng giữa các lá, người làm thí nghiệm phải làm gì?","options":["Nhỏ giọt nước giống nhau lên mỗi lá","Chỉ xem một lá","Mỗi lá nhỏ lượng nước khác"],"correct":0,"explanation":"Chỉ thay đổi một thứ (loại lá), giữ nguyên các thứ khác thì kết quả mới đáng tin."}]'::jsonb where id = 'act_kh_01' and quiz = '[{"id":"act_kh_01_q1","prompt":"Trên lá khoai môn, giọt nước tròn và lăn đi. Vì sao?","options":["Lá có lớp phấn mỏng, không thấm nước","Lá khoai môn rất nóng","Nước trên lá khoai nặng hơn"],"correct":0,"explanation":"Lớp phấn làm lá không thấm nước nên giọt nước co tròn lại."},{"id":"act_kh_01_q2","prompt":"Muốn so sánh các lá cho công bằng, em nên làm thế nào?","options":["Nhỏ giọt nước giống nhau lên mỗi lá","Lá nào nhỏ giọt to, lá nào nhỏ giọt bé","Chỉ cần nhìn một lá"],"correct":0,"explanation":"Giữ mọi thứ giống nhau, chỉ đổi loại lá, mới biết khác biệt là do lá."}]'::jsonb;
update activities set quiz = '[{"id":"act_kh_02_q1","prompt":"Ai làm công việc theo dõi bầu trời, mây, mưa nắng mỗi ngày?","options":["Người quan trắc khí tượng","Thợ điện","Người bán hàng"],"correct":0,"explanation":"Trạm khí tượng có người ghi lại mây, mưa, nắng mỗi ngày để dự báo thời tiết."},{"id":"act_kh_02_q2","prompt":"Khi quan sát bầu trời ban đêm, việc quan trọng nhất là gì?","options":["Ghi hoặc vẽ lại điều mình thấy","Nhìn qua rồi quên","Đoán bừa không cần nhìn"],"correct":0,"explanation":"Người làm khoa học luôn ghi chép lại để so sánh các lần quan sát."}]'::jsonb where id = 'act_kh_02' and quiz = '[{"id":"act_kh_02_q1","prompt":"Chòm Bắc Đẩu có mấy ngôi sao sáng xếp hình cái gáo?","options":["7 ngôi sao","3 ngôi sao","12 ngôi sao"],"correct":0,"explanation":"Bắc Đẩu gồm 7 ngôi sao sáng, xếp như cái gáo múc nước."},{"id":"act_kh_02_q2","prompt":"Lúc nào dễ nhìn thấy sao nhất?","options":["Buổi tối trời quang, ít mây","Buổi trưa nắng to","Buổi tối có nhiều mây đen"],"correct":0,"explanation":"Trời tối và quang mây thì ánh sao không bị che."}]'::jsonb;
update activities set quiz = '[{"id":"act_kh_03_q1","prompt":"Quan sát nồi nước rồi giải thích bằng lời giống việc của ai?","options":["Người nghiên cứu, giáo viên khoa học","Thợ may","Người bán rau"],"correct":0,"explanation":"Nhà nghiên cứu và giáo viên khoa học quan sát hiện tượng rồi giải thích vì sao."},{"id":"act_kh_03_q2","prompt":"Khi quan sát nồi nước đang đun, điều an toàn nhất là gì?","options":["Đứng xa vừa đủ, có người lớn ở gần","Ghé sát mặt vào nồi","Thò tay thử độ nóng"],"correct":0,"explanation":"Hơi nước sôi gây bỏng rất nhanh, quan sát từ xa là đủ."}]'::jsonb where id = 'act_kh_03' and quiz = '[{"id":"act_kh_03_q1","prompt":"Bọt khí nổi lên khi đun nước sôi chủ yếu là gì?","options":["Hơi nước","Bụi trong nước","Khói từ bếp"],"correct":0,"explanation":"Nước ở đáy nồi nóng nhất, biến thành hơi nước rồi nổi lên thành bọt."},{"id":"act_kh_03_q2","prompt":"Khi quan sát nồi nước đang đun, em cần nhớ điều gì?","options":["Đứng xa vừa đủ và có người lớn ở gần","Ghé sát mặt vào nồi cho rõ","Thò tay vào thử độ nóng"],"correct":0,"explanation":"Hơi nước và nước sôi có thể gây bỏng rất nặng."}]'::jsonb;
update activities set instructions = array['Chọn 1 điều em thắc mắc hôm nay (vì sao lá đổi màu...).', 'Hỏi người lớn hoặc nhớ để tra cứu khi có mạng.', 'Ghi lại câu hỏi và câu trả lời tìm được.']::text[] where id = 'act_kh_04' and instructions = array['Chọn 1 điều em thắc mắc hôm nay (vì sao trời có mây, vì sao lá đổi màu...).', 'Hỏi người lớn hoặc nhớ để tra cứu khi có mạng.', 'Ghi lại câu hỏi và câu trả lời tìm được.']::text[];
update activities set quiz = '[{"id":"act_kh_04_q1","prompt":"Đặt câu hỏi \"vì sao\" rồi đi tìm câu trả lời là việc chính của ai?","options":["Nhà nghiên cứu khoa học","Thợ hàn","Người lái xe"],"correct":0,"explanation":"Nhà nghiên cứu bắt đầu từ một câu hỏi, rồi tìm cách kiểm chứng câu trả lời."},{"id":"act_kh_04_q2","prompt":"Tìm được câu trả lời, người làm khoa học kiểm tra lại bằng cách nào?","options":["Hỏi thầy cô, tra sách đáng tin","Tự đoán rồi coi là đúng","Tin ngay tin đồn"],"correct":0,"explanation":"Câu trả lời cần được kiểm tra bằng nguồn đáng tin hoặc thí nghiệm."}]'::jsonb where id = 'act_kh_04' and quiz = '[{"id":"act_kh_04_q1","prompt":"Cầu vồng thường xuất hiện khi nào?","options":["Có nắng chiếu qua những giọt mưa","Trời tối không có trăng","Trời khô hanh, không có nước"],"correct":0,"explanation":"Ánh nắng đi qua giọt mưa bị tách thành nhiều màu."},{"id":"act_kh_04_q2","prompt":"Có một thắc mắc \"vì sao\", cách nào tốt để tìm câu trả lời?","options":["Hỏi thầy cô, người lớn hoặc tra sách","Tự đoán rồi coi là đúng luôn","Bỏ qua vì không quan trọng"],"correct":0,"explanation":"Kiểm tra với nguồn đáng tin giúp em biết mình đoán đúng hay sai."}]'::jsonb;
update activities set quiz = '[{"id":"act_kt_01_q1","prompt":"Tháo một vật ra xem bên trong rồi lắp lại giống việc của ai?","options":["Thợ sửa chữa thiết bị, xe điện","Giáo viên dạy văn","Người bán rau"],"correct":0,"explanation":"Thợ sửa chữa phải biết từng bộ phận nằm ở đâu, tháo ra rồi lắp lại đúng."},{"id":"act_kt_01_q2","prompt":"Khi tháo một đồ vật, thợ sửa chữa thường làm gì để lắp lại được?","options":["Xếp linh kiện theo thứ tự tháo","Để linh kiện lẫn lộn","Vứt bớt ốc nhỏ"],"correct":0,"explanation":"Xếp theo thứ tự hoặc chụp ảnh từng bước thì lắp lại không bị thiếu."}]'::jsonb where id = 'act_kt_01' and quiz = '[{"id":"act_kt_01_q1","prompt":"Trước khi tháo một đồ vật, em cần làm gì?","options":["Xin phép người lớn và chọn đồ cũ không quan trọng","Tháo ngay điện thoại của bố mẹ","Dùng búa đập cho nhanh"],"correct":0,"explanation":"Đồ cũ, được phép thì hỏng cũng không sao và an toàn hơn."},{"id":"act_kt_01_q2","prompt":"Lò xo trong bút bi bấm dùng để làm gì?","options":["Đẩy ruột bút thụt vào sau khi bấm","Làm bút nặng hơn","Giữ cho mực không bị khô"],"correct":0,"explanation":"Bấm thì lò xo bị nén; bấm lần nữa lò xo đẩy ruột bút thụt vào."}]'::jsonb;
update activities set quiz = '[{"id":"act_kt_02_q1","prompt":"Tìm đúng chỗ hỏng rồi sửa là việc hằng ngày của ai?","options":["Thợ sửa chữa","Người dẫn chương trình","Người trồng rau"],"correct":0,"explanation":"Thợ sửa chữa luôn tìm nguyên nhân hỏng trước, rồi mới sửa."},{"id":"act_kt_02_q2","prompt":"Trước khi sửa một đồ dùng điện, việc đầu tiên phải làm là gì?","options":["Rút phích cắm, ngắt điện","Sửa luôn khi đang cắm điện","Dùng tay ướt cho mát"],"correct":0,"explanation":"Thợ điện luôn ngắt điện trước khi sửa để không bị điện giật."}]'::jsonb where id = 'act_kt_02' and quiz = '[{"id":"act_kt_02_q1","prompt":"Ghế lung lay vì con ốc ở chân bị lỏng. Em nên làm gì?","options":["Siết lại con ốc bằng tua vít","Sơn lại ghế","Vứt ghế đi ngay"],"correct":0,"explanation":"Nhiều hỏng hóc nhỏ chỉ cần siết lại hoặc chêm cho chắc."},{"id":"act_kt_02_q2","prompt":"Đồ nào em KHÔNG nên tự sửa khi chưa có người lớn?","options":["Ổ cắm điện bị hở dây","Dây giày bị rối","Chân bàn bị kênh"],"correct":0,"explanation":"Đồ điện có thể gây giật, phải để người lớn hoặc thợ sửa."}]'::jsonb;
update activities set instructions = array['Chọn 1 hệ thống quen thuộc: bóng đèn - công tắc, vòi nước...', 'Vẽ sơ đồ đơn giản bằng giấy bút.', 'Kiểm tra lại thực tế xem có đúng không.']::text[] where id = 'act_kt_03' and instructions = array['Chọn 1 căn phòng hoặc 1 hệ thống quen thuộc (bóng đèn - công tắc, vòi nước...).', 'Vẽ sơ đồ đơn giản bằng giấy bút.', 'Kiểm tra lại thực tế xem có đúng không.']::text[];
update activities set quiz = '[{"id":"act_kt_03_q1","prompt":"Vẽ sơ đồ đường điện trong phòng giống việc của ai?","options":["Thợ điện, kỹ sư điện","Người bán hàng","Thợ cắt tóc"],"correct":0,"explanation":"Thợ điện và kỹ sư điện vẽ sơ đồ trước khi lắp điện cho một ngôi nhà."},{"id":"act_kt_03_q2","prompt":"Vì sao thợ điện cần sơ đồ trước khi lắp điện?","options":["Biết đặt dây, ổ cắm đúng chỗ","Để trang trí tường","Không cần, lắp bừa được"],"correct":0,"explanation":"Có sơ đồ thì lắp đúng, an toàn, sau này sửa cũng dễ tìm dây."}]'::jsonb where id = 'act_kt_03' and quiz = '[{"id":"act_kt_03_q1","prompt":"Trên sơ đồ đường nước, mũi tên dùng để chỉ điều gì?","options":["Chiều nước chảy","Màu của nước","Giá tiền của ống nước"],"correct":0,"explanation":"Mũi tên cho người xem biết nước đi từ đâu đến đâu."},{"id":"act_kt_03_q2","prompt":"Vẽ sơ đồ xong, bước cuối nên làm gì?","options":["So lại với thực tế xem có đúng không","Tô màu thật đẹp","Cất đi, không cần xem lại"],"correct":0,"explanation":"So với thực tế giúp em phát hiện chỗ vẽ sai."}]'::jsonb;
update activities set quiz = '[{"id":"act_nl_01_q1","prompt":"Nhìn lá, thân, đất để đoán cây khỏe không là việc của ai?","options":["Kỹ thuật viên nông nghiệp, khuyến nông","Thợ điện","Người lái xe"],"correct":0,"explanation":"Kỹ thuật viên nông nghiệp đi thăm vườn, nhìn lá và đất để phát hiện cây bệnh sớm."},{"id":"act_nl_01_q2","prompt":"Thấy lá cây vàng, đốm lạ, kỹ thuật viên nông nghiệp làm gì trước?","options":["Quan sát kỹ, tìm nguyên nhân","Phun thuốc ngay thật nhiều","Chặt bỏ cả cây"],"correct":0,"explanation":"Phải biết cây thiếu nước, thiếu phân hay bị sâu thì mới chữa đúng."}]'::jsonb where id = 'act_nl_01' and quiz = '[{"id":"act_nl_01_q1","prompt":"Cây có lá vàng ở gốc, đất khô và nứt. Cây có thể đang thiếu gì?","options":["Thiếu nước","Thừa nước","Thiếu bóng tối"],"correct":0,"explanation":"Đất khô nứt và lá vàng là dấu hiệu cây thiếu nước."},{"id":"act_nl_01_q2","prompt":"Nên tưới cây vào lúc nào trong ngày?","options":["Sáng sớm hoặc chiều mát","Giữa trưa nắng gắt","Lúc nào cũng như nhau"],"correct":0,"explanation":"Trưa nắng, nước bốc hơi nhanh và cây dễ bị sốc nóng."}]'::jsonb;
update activities set quiz = '[{"id":"act_nl_02_q1","prompt":"Xem màu, độ ẩm của đất để chọn cây trồng là việc của ai?","options":["Kỹ thuật viên nông nghiệp, kiểm nghiệm đất","Thợ cắt tóc","Người bán điện thoại"],"correct":0,"explanation":"Biết đất thế nào thì chọn được cây hợp đất, năng suất cao hơn."},{"id":"act_nl_02_q2","prompt":"Lấy mẫu đất xong, em nên làm gì?","options":["Rửa tay sạch","Đưa tay lên miệng","Không cần rửa tay"],"correct":0,"explanation":"Đất có thể có vi khuẩn, người làm nông luôn rửa tay sau khi làm việc với đất."}]'::jsonb where id = 'act_nl_02' and quiz = '[{"id":"act_nl_02_q1","prompt":"Loại đất nào thường hợp trồng rau?","options":["Đất nâu sẫm, tơi xốp và hơi ẩm","Đất khô cứng, nứt nẻ","Cát khô hoàn toàn"],"correct":0,"explanation":"Đất tơi, ẩm giữ được nước và không khí cho rễ."},{"id":"act_nl_02_q2","prompt":"Đất \"tơi xốp\" nghĩa là gì?","options":["Đất có nhiều khe hở, bóp nhẹ là vỡ ra","Đất dính chặt thành cục cứng","Đất toàn là đá"],"correct":0,"explanation":"Khe hở trong đất giữ không khí và nước cho rễ cây."}]'::jsonb;
update activities set quiz = '[{"id":"act_nl_03_q1","prompt":"Theo dõi con vật ăn uống, phát hiện con ốm là việc của ai?","options":["Thú y, người chăn nuôi","Thợ xây","Người dẫn chương trình"],"correct":0,"explanation":"Người làm thú y và chăn nuôi quan sát con vật mỗi ngày để phát hiện bệnh sớm."},{"id":"act_nl_03_q2","prompt":"Dọn chuồng trại xong, việc quan trọng là gì?","options":["Rửa tay sạch bằng xà phòng","Đi ăn luôn","Lau tay vào quần áo"],"correct":0,"explanation":"Chuồng trại có nhiều vi khuẩn, rửa tay giúp không mang bệnh vào người."}]'::jsonb where id = 'act_nl_03' and quiz = '[{"id":"act_nl_03_q1","prompt":"Con gà đứng riêng, ít ăn, xù lông. Có thể nó đang làm sao?","options":["Có thể bị mệt hoặc bị ốm","Đang rất khỏe","Đang đói nên đòi ăn"],"correct":0,"explanation":"Đứng riêng, bỏ ăn, xù lông thường là dấu hiệu vật nuôi không khỏe."},{"id":"act_nl_03_q2","prompt":"Thấy vật nuôi có dấu hiệu ốm, em nên làm gì?","options":["Báo cho bố mẹ hoặc người lớn","Tự cho uống thuốc của người","Không cần để ý"],"correct":0,"explanation":"Người lớn hoặc cán bộ thú y mới biết cách chữa đúng."}]'::jsonb;
update activities set quiz = '[{"id":"act_nl_04_q1","prompt":"Phân loại rác để tái sử dụng giống việc của ai?","options":["Người làm môi trường","Thợ điện","Người bán vé"],"correct":0,"explanation":"Người làm môi trường thu gom, phân loại rác để bản làng sạch và tái chế được."},{"id":"act_nl_04_q2","prompt":"Nhặt rác có mảnh vỡ, cần làm gì để an toàn?","options":["Đeo găng tay hoặc dùng que gắp","Nhặt bằng tay không","Giẫm cho vỡ nhỏ"],"correct":0,"explanation":"Mảnh chai, kim loại sắc dễ làm đứt tay."}]'::jsonb where id = 'act_nl_04' and quiz = '[{"id":"act_nl_04_q1","prompt":"Loại rác nào có thể tái chế hoặc bán ve chai?","options":["Vỏ chai nhựa","Thức ăn thừa","Giấy ăn đã dùng"],"correct":0,"explanation":"Chai nhựa có thể làm chậu cây hoặc bán ve chai."},{"id":"act_nl_04_q2","prompt":"Túi ni lông đã dùng nên xử lý thế nào?","options":["Gom lại, bỏ đúng nơi thu gom","Đốt ngay tại chỗ","Vứt xuống suối"],"correct":0,"explanation":"Đốt ni lông sinh khói độc; vứt xuống suối làm bẩn nguồn nước."}]'::jsonb;
update activities set quiz = '[{"id":"act_kd_01_q1","prompt":"Tính tổng tiền các món trong bữa ăn giống việc của ai?","options":["Người bán hàng, kế toán hợp tác xã","Thợ điện","Người trồng rừng"],"correct":0,"explanation":"Người bán hàng và kế toán ngày nào cũng cộng chi phí để biết lời hay lỗ."},{"id":"act_kd_01_q2","prompt":"Chủ quán ăn ở bản tính chi phí để làm gì?","options":["Đặt giá bán có lời","Để khoe với khách","Không để làm gì"],"correct":0,"explanation":"Biết chi phí thì mới đặt được giá bán không bị lỗ."}]'::jsonb where id = 'act_kd_01' and quiz = '[{"id":"act_kd_01_q1","prompt":"Gạo 10.000đ, rau 5.000đ, trứng 12.000đ, mắm muối 3.000đ. Cả bữa hết bao nhiêu?","options":["30.000đ","25.000đ","35.000đ"],"correct":0,"explanation":"10.000 + 5.000 + 12.000 + 3.000 = 30.000đ."},{"id":"act_kd_01_q2","prompt":"Bữa ăn 30.000đ cho 5 người. Mỗi người khoảng bao nhiêu?","options":["6.000đ","15.000đ","3.000đ"],"correct":0,"explanation":"30.000 : 5 = 6.000đ mỗi người."}]'::jsonb;
update activities set quiz = '[{"id":"act_kd_02_q1","prompt":"Nghĩ ra sản phẩm rồi tính xem ai sẽ mua giống việc của ai?","options":["Người buôn bán, mở cửa hàng","Thợ xây","Bác sĩ"],"correct":0,"explanation":"Người buôn bán phải biết khách cần gì trước khi làm sản phẩm."},{"id":"act_kd_02_q2","prompt":"Trước khi bán thật, người bán nên làm gì?","options":["Hỏi thử vài người có muốn mua không","Làm thật nhiều rồi mới hỏi","Đặt giá thật cao"],"correct":0,"explanation":"Hỏi trước giúp biết sản phẩm có người cần, đỡ làm ra rồi không bán được."}]'::jsonb where id = 'act_kd_02' and quiz = '[{"id":"act_kd_02_q1","prompt":"Vòng tay bán 5.000đ, tốn 2.000đ tiền hạt. Mỗi chiếc lãi bao nhiêu?","options":["3.000đ","7.000đ","2.000đ"],"correct":0,"explanation":"Lãi = giá bán - chi phí = 5.000 - 2.000 = 3.000đ."},{"id":"act_kd_02_q2","prompt":"Câu quảng cáo tốt nên thế nào?","options":["Ngắn, nói rõ điểm hay của sản phẩm","Thật dài, kể mọi thứ","Nói xấu sản phẩm của người khác"],"correct":0,"explanation":"Câu ngắn, rõ điểm hay thì người nghe dễ nhớ."}]'::jsonb;
update activities set quiz = '[{"id":"act_kd_03_q1","prompt":"Người bán hàng ở chợ làm những việc gì mỗi ngày?","options":["Mời khách, tính tiền, nhập hàng","Chỉ ngồi chờ khách","Sửa xe cho khách"],"correct":0,"explanation":"Người bán hàng mời khách, tính tiền nhanh, nhớ giá và nhập hàng mới."},{"id":"act_kd_03_q2","prompt":"Điều gì giúp người bán hàng giữ được khách quen?","options":["Vui vẻ, bán đúng giá, hàng tốt","Nói dối về hàng","Cân thiếu cho có lời"],"correct":0,"explanation":"Khách quay lại khi người bán thật thà và hàng tốt."}]'::jsonb where id = 'act_kd_03' and quiz = '[{"id":"act_kd_03_q1","prompt":"Cô bán rau hay chào khách và cho thêm hành. Việc đó giúp gì?","options":["Khách vui và hay quay lại mua","Cô bán được giá gấp đôi","Không giúp gì"],"correct":0,"explanation":"Khách quen quay lại là điều quan trọng với người bán hàng."},{"id":"act_kd_03_q2","prompt":"Khi quan sát người bán hàng, em nên chú ý điều gì?","options":["Cách họ chào khách, giới thiệu và tính tiền","Họ mặc áo màu gì","Họ dùng điện thoại loại gì"],"correct":0,"explanation":"Đó là những kỹ năng chính của nghề bán hàng."}]'::jsonb;
update activities set quiz = '[{"id":"act_kd_04_q1","prompt":"Ghi chép thu chi, tiết kiệm từng khoản là việc chính của ai?","options":["Kế toán hợp tác xã","Thợ mộc","Người quay video"],"correct":0,"explanation":"Kế toán ghi lại mọi khoản thu chi để hợp tác xã biết còn bao nhiêu tiền."},{"id":"act_kd_04_q2","prompt":"Muốn tiết kiệm được, việc đầu tiên nên làm là gì?","options":["Đặt mục tiêu và ghi lại khoản chi","Tiêu hết rồi tính sau","Không cần ghi chép"],"correct":0,"explanation":"Có mục tiêu và sổ ghi chép thì biết mình đã tiêu vào đâu."}]'::jsonb where id = 'act_kd_04' and quiz = '[{"id":"act_kd_04_q1","prompt":"Mỗi ngày bớt 3.000đ tiền quà vặt. Sau 7 ngày em để dành được bao nhiêu?","options":["21.000đ","10.000đ","30.000đ"],"correct":0,"explanation":"3.000 x 7 = 21.000đ."},{"id":"act_kd_04_q2","prompt":"Mục tiêu tiết kiệm nào cụ thể nhất?","options":["Để dành 20.000đ trong tuần này để mua sách","Em sẽ cố gắng tiết kiệm","Khi nào có tiền thì tiết kiệm"],"correct":0,"explanation":"Mục tiêu có số tiền, thời hạn và lý do thì dễ làm theo."}]'::jsonb;
update activities set quiz = '[{"id":"act_sk_01_q1","prompt":"Kiểm tra ánh sáng, tư thế ngồi học để bảo vệ mắt, lưng là việc của ai?","options":["Nhân viên y tế trường học","Thợ xây","Người bán hàng"],"correct":0,"explanation":"Nhân viên y tế trường học nhắc học sinh ngồi đúng, đủ sáng để bảo vệ mắt và lưng."},{"id":"act_sk_01_q2","prompt":"Muốn làm nhân viên y tế, em cần học tới đâu?","options":["Hết THPT rồi học cao đẳng, đại học y","Chỉ cần hết lớp 9","Không cần học"],"correct":0,"explanation":"Nghề y bắt buộc học hết THPT rồi học trường cao đẳng hoặc đại học y."}]'::jsonb where id = 'act_sk_01' and quiz = '[{"id":"act_sk_01_q1","prompt":"Khi đọc viết, mắt nên cách vở khoảng bao nhiêu?","options":["Khoảng 30 cm","Khoảng 5 cm","Khoảng 1 mét"],"correct":0,"explanation":"Cách khoảng 30 cm giúp mắt đỡ mỏi, tránh cận thị."},{"id":"act_sk_01_q2","prompt":"Góc học tập thế nào là tốt cho mắt?","options":["Đủ ánh sáng, ví dụ gần cửa sổ","Càng tối càng dễ tập trung","Đèn chiếu thẳng vào mắt"],"correct":0,"explanation":"Học chỗ thiếu sáng làm mắt phải điều tiết nhiều, nhanh mỏi."}]'::jsonb;
update activities set quiz = '[{"id":"act_sk_02_q1","prompt":"Ai thường xử lý vết đứt tay, bỏng nhẹ cho người dân ở xã?","options":["Y sĩ, điều dưỡng ở trạm y tế","Thợ điện","Người bán rau"],"correct":0,"explanation":"Y sĩ và điều dưỡng ở trạm y tế xã sơ cứu và hướng dẫn người dân."},{"id":"act_sk_02_q2","prompt":"Bị bỏng nhẹ, việc đầu tiên nên làm là gì?","options":["Xả nước mát sạch vào chỗ bỏng","Bôi kem đánh răng","Chọc vỡ chỗ phồng"],"correct":0,"explanation":"Nước mát làm dịu và giảm tổn thương; không bôi các thứ lạ lên vết bỏng."}]'::jsonb where id = 'act_sk_02' and quiz = '[{"id":"act_sk_02_q1","prompt":"Bị bỏng nhẹ, việc đầu tiên nên làm là gì?","options":["Xả nước mát lên vết bỏng khoảng 15 phút","Bôi kem đánh răng","Chườm đá lạnh"],"correct":0,"explanation":"Nước mát làm dịu và giảm tổn thương; kem đánh răng, đá lạnh làm vết bỏng nặng hơn."},{"id":"act_sk_02_q2","prompt":"Bị đứt tay nhẹ, nên làm gì?","options":["Rửa sạch, ấn nhẹ cho cầm máu rồi băng lại","Để nguyên cho tự khô","Bôi đất lên vết thương"],"correct":0,"explanation":"Vết thương sạch và được băng sẽ ít bị nhiễm trùng."}]'::jsonb;
update activities set quiz = '[{"id":"act_sk_02b_q1","prompt":"Hỏi thăm, chăm sóc người ốm mỗi ngày là việc chính của ai?","options":["Điều dưỡng","Thợ hàn","Người quay video"],"correct":0,"explanation":"Điều dưỡng theo dõi, chăm sóc người bệnh hằng ngày ở trạm y tế, bệnh viện."},{"id":"act_sk_02b_q2","prompt":"Khi người thân mệt, em nên làm gì?","options":["Hỏi han, giúp việc nhỏ, báo người lớn","Không để ý","Tự đưa thuốc bất kỳ"],"correct":0,"explanation":"Hỏi han và báo người lớn là đủ; không tự cho uống thuốc."}]'::jsonb where id = 'act_sk_02b' and quiz = '[{"id":"act_sk_02b_q1","prompt":"Khi hỏi thăm người thân đang mệt, điều quan trọng nhất là gì?","options":["Lắng nghe và giúp một việc nhỏ","Hỏi thật nhanh rồi đi chơi","Bảo họ tự lo"],"correct":0,"explanation":"Được lắng nghe và giúp đỡ làm người thân thấy được quan tâm."},{"id":"act_sk_02b_q2","prompt":"Bà bị đau lưng. Việc nhỏ nào em có thể giúp?","options":["Rót nước ấm và nhắc bà nghỉ ngơi","Nhờ bà bê đồ nặng giúp em","Tự lấy thuốc cho bà uống"],"correct":0,"explanation":"Thuốc phải do người lớn hoặc nhân viên y tế quyết định."}]'::jsonb;
update activities set quiz = '[{"id":"act_nt_01_q1","prompt":"Vẽ nhanh lại một cảnh bằng vài nét giống việc của ai?","options":["Họa sĩ, người thiết kế đồ họa","Thợ điện","Y tá"],"correct":0,"explanation":"Người thiết kế phác thảo nhanh ý tưởng trước khi làm sản phẩm thật."},{"id":"act_nt_01_q2","prompt":"Người thiết kế làm gì trước khi vẽ bản đẹp?","options":["Phác thảo nhiều bản nháp","Vẽ ngay bản cuối","Không cần ý tưởng"],"correct":0,"explanation":"Phác thảo nhanh giúp thử nhiều ý tưởng rồi chọn cái hay nhất."}]'::jsonb where id = 'act_nt_01' and quiz = '[{"id":"act_nt_01_q1","prompt":"Trong hoạt động vẽ nhanh, điều gì quan trọng nhất?","options":["Ghi lại khoảnh khắc em nhớ, không cần đẹp","Vẽ thật đẹp như họa sĩ","Vẽ đúng tỉ lệ từng chi tiết"],"correct":0,"explanation":"Vẽ nhanh là để lưu lại cảm xúc, không phải để thi vẽ đẹp."},{"id":"act_nt_01_q2","prompt":"Đặt tên cho bức vẽ giúp gì?","options":["Nói lên điều em muốn kể trong tranh","Làm tranh nặng hơn","Không giúp gì"],"correct":0,"explanation":"Tên tranh giúp người xem hiểu câu chuyện của em."}]'::jsonb;
update activities set quiz = '[{"id":"act_nt_02_q1","prompt":"Viết lời ngắn, có vần cho một tiết mục văn nghệ là việc của ai?","options":["Người viết kịch bản, làm truyền thông","Thợ hàn","Kế toán"],"correct":0,"explanation":"Người viết kịch bản và truyền thông viết lời dẫn, lời bài để tiết mục hấp dẫn."},{"id":"act_nt_02_q2","prompt":"Viết xong, người viết thường làm gì để hay hơn?","options":["Đọc to, sửa chỗ chưa hay","Không đọc lại","Xóa hết"],"correct":0,"explanation":"Đọc to giúp nghe ra vần, nhịp; sửa vài lần thì bài hay hơn."}]'::jsonb where id = 'act_nt_02' and quiz = '[{"id":"act_nt_02_q1","prompt":"Bài thơ/vè 4 câu ở hoạt động này có cần vần thật chuẩn không?","options":["Không cần, quan trọng là em tự viết","Bắt buộc phải vần chuẩn","Phải chép bài có sẵn"],"correct":0,"explanation":"Điều quan trọng là em tự diễn đạt ý của mình."},{"id":"act_nt_02_q2","prompt":"Vì sao nên đọc to bài thơ cho chính mình nghe?","options":["Để nghe nhịp điệu và sửa chỗ chưa xuôi","Để hàng xóm nghe thấy","Không có lý do gì"],"correct":0,"explanation":"Đọc to giúp em phát hiện câu nào đọc còn vấp."}]'::jsonb;
update activities set quiz = '[{"id":"act_nt_03_q1","prompt":"Chọn góc chụp lạ cho một đồ vật quen là việc của ai?","options":["Người chụp ảnh, quay phim","Thợ xây","Người bán thuốc"],"correct":0,"explanation":"Người chụp ảnh chọn góc, ánh sáng để vật quen trông mới lạ, hấp dẫn."},{"id":"act_nt_03_q2","prompt":"Muốn chụp người khác, người chụp ảnh phải làm gì trước?","options":["Xin phép người đó","Chụp lén","Đăng lên mạng ngay"],"correct":0,"explanation":"Tôn trọng người được chụp: luôn hỏi ý trước khi chụp và đăng ảnh."}]'::jsonb where id = 'act_nt_03' and quiz = '[{"id":"act_nt_03_q1","prompt":"Chụp từ sát mặt đất nhìn lên gọi là góc chụp gì?","options":["Góc thấp","Góc cao","Góc ngang"],"correct":0,"explanation":"Góc thấp làm vật trông to và lạ hơn bình thường."},{"id":"act_nt_03_q2","prompt":"Chụp một vật từ nhiều góc khác nhau giúp em điều gì?","options":["Thấy vật quen thuộc theo cách mới lạ","Tốn pin hơn","Ảnh chắc chắn bị mờ"],"correct":0,"explanation":"Đổi góc nhìn là một cách sáng tạo của người chụp ảnh."}]'::jsonb;
update activities set quiz = '[{"id":"act_xh_01_q1","prompt":"Giảng lại một điều cho em nhỏ hiểu giống việc chính của ai?","options":["Giáo viên","Thợ xây","Người bán hàng"],"correct":0,"explanation":"Giáo viên mỗi ngày tìm cách giảng sao cho học sinh hiểu."},{"id":"act_xh_01_q2","prompt":"Muốn làm giáo viên, em cần học tới đâu?","options":["Hết THPT rồi học sư phạm","Chỉ cần hết lớp 9","Không cần học"],"correct":0,"explanation":"Giáo viên bắt buộc học hết THPT rồi học cao đẳng hoặc đại học sư phạm."}]'::jsonb where id = 'act_xh_01' and quiz = '[{"id":"act_xh_01_q1","prompt":"Dùng quả cam và đèn pin, em giải thích được hiện tượng gì?","options":["Vì sao có ngày và đêm","Vì sao trời mưa","Vì sao lá rụng"],"correct":0,"explanation":"Trái Đất (quả cam) quay, nửa nào hướng về Mặt Trời (đèn) là ban ngày."},{"id":"act_xh_01_q2","prompt":"Giảng xong, làm gì để biết người nghe đã hiểu chưa?","options":["Hỏi lại xem họ đã hiểu chưa","Nói thật nhanh rồi thôi","Bắt họ chép lại"],"correct":0,"explanation":"Hỏi lại là cách thầy cô kiểm tra học sinh có hiểu bài."}]'::jsonb;
